from numpy.linalg import lstsq
from scipy.optimize import least_squares
t=df['t'];A=df['A'];y=df['dA_dt']
def mk(name):
    def resid(th):
        p,k,q=th[0],th[1],th[2]
        if name=='exp': h=np.exp(q*t)
        elif name=='pow': h=t**q
        elif name=='shift': h=1/(t+q)
        elif name=='expA': h=np.exp(q*A)
        X=np.column_stack([np.sqrt(t),A**p*np.exp(k*t),h])
        c=lstsq(X,y,rcond=None)[0]
        return X@c-y
    return resid
for name,starts in [('exp',[-1,0.5]),('pow',[1,2]),('shift',[-1,0.5]),('expA',[-1,0.5])]:
    bestv=None
    for p0 in [2,3]:
        for k0 in [-0.1,-0.2]:
            for q0 in starts:
                try:
                    r=least_squares(mk(name),[p0,k0,q0])
                    v=np.mean(r.fun**2)/np.var(y)
                    if bestv is None or v<bestv[0]: bestv=(v,r.x)
                except Exception as e: pass
    print(name,bestv)

